<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>RedRoom Fitness — The Best HIIT Workout in the World</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{--red:#E63946;--bg:#111;--bg-alt:#1a1a1a;--bg-card:#1e1e1e;--white:#fff;--gray:#a0a0a0;--gray-light:#ccc;--font-heading:'Oswald',sans-serif;--font-body:'Inter',sans-serif;--max-w:1200px;--transition:0.3s ease}
html{scroll-behavior:smooth}
body{font-family:var(--font-body);background:var(--bg);color:var(--white);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{cursor:pointer;font-family:var(--font-body);border:none;background:none}
.container{max-width:var(--max-w);margin:0 auto;padding:0 24px}

/* Top Promo Bar */
.promo-bar{background:var(--red);text-align:center;padding:10px 16px;font-size:13px;font-weight:500;letter-spacing:0.5px}
.promo-bar a{text-decoration:underline;font-weight:600;margin-left:8px}

/* Navigation */
.nav{background:rgba(17,17,17,0.95);backdrop-filter:blur(12px);position:sticky;top:0;z-index:100;border-bottom:1px solid rgba(255,255,255,0.06)}
.nav-inner{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;max-width:var(--max-w);margin:0 auto}
.nav-logo{font-family:var(--font-heading);font-size:22px;font-weight:700;letter-spacing:2px;color:var(--red)}
.nav-links{display:flex;gap:28px;align-items:center}
.nav-links a{font-size:13px;font-weight:500;text-transform:uppercase;letter-spacing:1.2px;transition:color var(--transition)}
.nav-links a:hover{color:var(--red)}
.nav-utility{display:flex;gap:16px;align-items:center}
.nav-utility a{font-size:12px;text-transform:uppercase;letter-spacing:1px;font-weight:500}
.btn{display:inline-block;padding:12px 32px;font-family:var(--font-heading);font-size:14px;font-weight:600;text-transform:uppercase;letter-spacing:2px;transition:all var(--transition)}
.btn-red{background:var(--red);color:var(--white)}
.btn-red:hover{background:#c62f3a;transform:translateY(-1px)}
.btn-outline{border:2px solid var(--white);color:var(--white)}
.btn-outline:hover{background:var(--white);color:var(--bg)}
.btn-outline-red{border:2px solid var(--red);color:var(--red)}
.btn-outline-red:hover{background:var(--red);color:var(--white)}

/* Mobile nav toggle */
.nav-toggle{display:none;flex-direction:column;gap:5px;background:none;border:none;cursor:pointer;padding:4px}
.nav-toggle span{width:24px;height:2px;background:var(--white);transition:var(--transition)}

/* Hero */
.hero{position:relative;min-height:90vh;display:flex;align-items:center;justify-content:center;text-align:center;overflow:hidden;background:linear-gradient(135deg,#1a0000 0%,#111 40%,#0a0a0a 100%)}
.hero::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% 30%,rgba(230,57,70,0.15) 0%,transparent 70%)}
.hero-content{position:relative;z-index:2;padding:60px 24px}
.hero h1{font-family:var(--font-heading);font-size:clamp(40px,8vw,80px);font-weight:700;text-transform:uppercase;letter-spacing:4px;line-height:1.05;margin-bottom:24px}
.hero h1 span{color:var(--red)}
.hero p{font-size:clamp(14px,2vw,18px);color:var(--gray-light);max-width:600px;margin:0 auto 40px;line-height:1.7}
.hero-ctas{display:flex;gap:16px;justify-content:center;flex-wrap:wrap}
.hero-accent{position:absolute;width:400px;height:400px;border-radius:50%;background:radial-gradient(circle,rgba(230,57,70,0.08) 0%,transparent 70%);top:-100px;right:-100px}

/* Section utility */
.section{padding:100px 0}
.section-title{font-family:var(--font-heading);font-size:clamp(28px,5vw,48px);font-weight:700;text-transform:uppercase;letter-spacing:3px;text-align:center;margin-bottom:16px}
.section-subtitle{text-align:center;color:var(--gray);max-width:650px;margin:0 auto 48px;font-size:15px;line-height:1.7}

/* Community Promo */
.community{background:var(--bg-alt)}
.community-inner{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.community-visual{position:relative;height:400px;background:linear-gradient(145deg,rgba(230,57,70,0.2),rgba(230,57,70,0.02));border-radius:4px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.community-visual-text{font-family:var(--font-heading);font-size:120px;font-weight:700;color:rgba(230,57,70,0.12);text-transform:uppercase;letter-spacing:8px;line-height:1}
.community-content h2{font-family:var(--font-heading);font-size:42px;text-transform:uppercase;letter-spacing:3px;margin-bottom:20px}
.community-content p{color:var(--gray-light);line-height:1.8;margin-bottom:32px;font-size:15px}

/* Two Ways */
.two-ways-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:48px}
.two-ways-card{background:var(--bg-card);padding:48px 40px;border:1px solid rgba(255,255,255,0.06);position:relative;overflow:hidden;transition:all var(--transition)}
.two-ways-card:hover{border-color:var(--red);transform:translateY(-4px)}
.two-ways-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--red);transform:scaleX(0);transition:transform var(--transition)}
.two-ways-card:hover::before{transform:scaleX(1)}
.two-ways-card h3{font-family:var(--font-heading);font-size:28px;text-transform:uppercase;letter-spacing:2px;margin-bottom:16px;color:var(--red)}
.two-ways-card p{color:var(--gray-light);line-height:1.7;font-size:14px}
.two-ways-card .card-number{font-family:var(--font-heading);font-size:80px;color:rgba(230,57,70,0.08);position:absolute;top:-10px;right:20px;font-weight:700}

/* Studio Experience */
.studio{background:linear-gradient(180deg,var(--bg) 0%,#1a0505 100%);text-align:center}
.studio .section-title{margin-bottom:20px}
.studio-description{color:var(--gray-light);max-width:700px;margin:0 auto 40px;line-height:1.8;font-size:15px}
.studio-tagline{font-family:var(--font-heading);font-size:18px;text-transform:uppercase;letter-spacing:3px;color:var(--red);margin-bottom:32px}

/* Free Trial CTA */
.free-trial{background:var(--red);text-align:center;padding:80px 24px;position:relative;overflow:hidden}
.free-trial::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(0,0,0,0.2) 0%,transparent 50%,rgba(0,0,0,0.1) 100%)}
.free-trial-content{position:relative;z-index:2}
.free-trial h2{font-family:var(--font-heading);font-size:clamp(32px,6vw,56px);text-transform:uppercase;letter-spacing:4px;margin-bottom:24px}
.free-trial .btn{background:var(--white);color:var(--red);font-size:16px;padding:16px 48px}
.free-trial .btn:hover{background:var(--bg);color:var(--white);transform:translateY(-2px)}

/* Lifestyle Carousel */
.carousel-section{background:var(--bg-alt);overflow:hidden}
.carousel-wrapper{position:relative;max-width:var(--max-w);margin:0 auto;padding:0 24px}
.carousel-track{display:flex;gap:20px;overflow:hidden;scroll-snap-type:x mandatory}
.carousel-slide{min-width:calc(33.333% - 14px);aspect-ratio:4/3;background:var(--bg-card);border:1px solid rgba(255,255,255,0.06);flex-shrink:0;scroll-snap-align:start;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center}
.carousel-slide-content{font-family:var(--font-heading);font-size:16px;text-transform:uppercase;letter-spacing:2px;color:var(--gray);text-align:center;padding:20px}
.carousel-nav{display:flex;gap:12px;justify-content:center;margin-top:32px}
.carousel-btn{width:48px;height:48px;border:2px solid rgba(255,255,255,0.2);background:transparent;color:var(--white);font-size:18px;display:flex;align-items:center;justify-content:center;transition:all var(--transition)}
.carousel-btn:hover{border-color:var(--red);color:var(--red)}
.carousel-dots{display:flex;gap:8px;align-items:center;justify-content:center;margin-top:20px}
.carousel-dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,0.2);transition:all var(--transition);cursor:pointer}
.carousel-dot.active{background:var(--red);width:24px;border-radius:4px}

/* Newsletter */
.newsletter{background:var(--bg);text-align:center}
.newsletter h2{font-family:var(--font-heading);font-size:32px;text-transform:uppercase;letter-spacing:3px;margin-bottom:12px}
.newsletter p{color:var(--gray);margin-bottom:32px;font-size:14px}
.newsletter-form{display:flex;gap:0;max-width:500px;margin:0 auto;position:relative}
.newsletter-form input{flex:1;padding:14px 20px;background:var(--bg-card);border:2px solid rgba(255,255,255,0.1);color:var(--white);font-size:14px;font-family:var(--font-body);outline:none;transition:border-color var(--transition)}
.newsletter-form input:focus{border-color:var(--red)}
.newsletter-form input::placeholder{color:var(--gray)}
.newsletter-form button{padding:14px 28px;background:var(--red);color:var(--white);font-family:var(--font-heading);font-size:14px;text-transform:uppercase;letter-spacing:2px;font-weight:600;border:none;transition:background var(--transition)}
.newsletter-form button:hover{background:#c62f3a}
.newsletter-msg{margin-top:12px;font-size:13px;min-height:20px}
.newsletter-msg.success{color:#4caf50}
.newsletter-msg.error{color:var(--red)}

/* Footer */
.footer{background:#0a0a0a;padding:60px 0 32px;border-top:1px solid rgba(255,255,255,0.06)}
.footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:40px;margin-bottom:48px}
.footer-col h4{font-family:var(--font-heading);font-size:14px;text-transform:uppercase;letter-spacing:2px;margin-bottom:20px;color:var(--red)}
.footer-col a{display:block;font-size:13px;color:var(--gray);padding:4px 0;transition:color var(--transition)}
.footer-col a:hover{color:var(--white)}
.footer-col select{background:var(--bg-card);color:var(--gray);border:1px solid rgba(255,255,255,0.1);padding:8px 12px;font-size:13px;font-family:var(--font-body);width:100%;margin-top:8px}
.footer-bottom{text-align:center;padding-top:32px;border-top:1px solid rgba(255,255,255,0.06);font-size:12px;color:var(--gray)}
.footer-logo{font-family:var(--font-heading);font-size:18px;font-weight:700;color:var(--red);letter-spacing:2px;margin-bottom:12px}

/* Responsive */
@media(max-width:900px){
  .nav-links{display:none;position:absolute;top:100%;left:0;right:0;background:rgba(17,17,17,0.98);flex-direction:column;padding:24px;gap:16px;border-bottom:1px solid rgba(255,255,255,0.06)}
  .nav-links.open{display:flex}
  .nav-toggle{display:flex}
  .nav-utility{display:none}
  .community-inner{grid-template-columns:1fr}
  .community-visual{height:250px}
  .two-ways-grid{grid-template-columns:1fr}
  .carousel-slide{min-width:calc(50% - 10px)}
  .footer-grid{grid-template-columns:1fr 1fr;gap:32px}
}
@media(max-width:600px){
  .hero{min-height:75vh}
  .hero-ctas{flex-direction:column;align-items:center}
  .section{padding:60px 0}
  .carousel-slide{min-width:calc(100% - 0px)}
  .footer-grid{grid-template-columns:1fr}
  .newsletter-form{flex-direction:column}
  .newsletter-form button{width:100%}
}
</style>
</head>
