<script>
// Carousel
let carouselIndex = 0;
const track = document.getElementById('carouselTrack');
const slides = track.querySelectorAll('.carousel-slide');
const dotsContainer = document.getElementById('carouselDots');
let slidesPerView = 3;

function updateSlidesPerView() {
  if (window.innerWidth <= 600) slidesPerView = 1;
  else if (window.innerWidth <= 900) slidesPerView = 2;
  else slidesPerView = 3;
}

function maxIndex() {
  return Math.max(0, slides.length - slidesPerView);
}

function buildDots() {
  dotsContainer.innerHTML = '';
  const total = maxIndex() + 1;
  for (let i = 0; i < total; i++) {
    const dot = document.createElement('div');
    dot.className = 'carousel-dot' + (i === carouselIndex ? ' active' : '');
    dot.onclick = () => { carouselIndex = i; updateCarousel(); };
    dotsContainer.appendChild(dot);
  }
}

function updateCarousel() {
  if (carouselIndex > maxIndex()) carouselIndex = maxIndex();
  if (carouselIndex < 0) carouselIndex = 0;
  const slideWidth = slides[0].offsetWidth + 20;
  track.style.transition = 'transform 0.4s ease';
  track.style.transform = `translateX(-${carouselIndex * slideWidth}px)`;
  buildDots();
}

function moveCarousel(dir) {
  carouselIndex += dir;
  updateCarousel();
}

window.addEventListener('resize', () => { updateSlidesPerView(); updateCarousel(); });
updateSlidesPerView();
buildDots();

// Touch/swipe
let touchStartX = 0;
track.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; }, {passive: true});
track.addEventListener('touchend', e => {
  const diff = touchStartX - e.changedTouches[0].clientX;
  if (Math.abs(diff) > 50) moveCarousel(diff > 0 ? 1 : -1);
}, {passive: true});

// Newsletter
function handleNewsletter(e) {
  e.preventDefault();
  const email = document.getElementById('newsletterEmail');
  const msg = document.getElementById('newsletterMsg');
  const val = email.value.trim();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(val)) {
    msg.textContent = 'Please enter a valid email address.';
    msg.className = 'newsletter-msg error';
    return false;
  }
  msg.textContent = 'Thank you for subscribing! Welcome to the RedRoom community.';
  msg.className = 'newsletter-msg success';
  email.value = '';
  return false;
}

// Country selector
function handleCountrySelect(val) {
  // Placeholder for region switching
}
</script>
